package grpcserver

import (
	"context"
	"log"

	"mw-telegram-bot/internal/bot"
	"mw-telegram-bot/pkg/grpcAutoGenerated/telegram-bot"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	emptypb "google.golang.org/protobuf/types/known/emptypb"
)

type TelegramGRPCServer struct {
	telegram.UnimplementedTelegramServiceServer
	bot *bot.TelegramBot
}

func NewTelegramGRPCServer(bot *bot.TelegramBot) *TelegramGRPCServer {
	return &TelegramGRPCServer{bot: bot}
}

func (s *TelegramGRPCServer) SendTelegramNotification(ctx context.Context, req *telegram.SendTelegramNotificationRequest) (*emptypb.Empty, error) {
	log.Printf("gRPC: SendTelegramNotification for user %s", req.UserUuid)

	userTelegramID, err := s.bot.GetUserTelegramID(ctx, req.UserUuid)
	if err != nil {
		return nil, status.Errorf(codes.NotFound, "user telegram ID not found: %v", err)
	}

	if userTelegramID == 0 {
		return nil, status.Errorf(codes.NotFound, "user has no linked telegram account")
	}

	err = s.bot.SendMessage(userTelegramID, req.Message)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "failed to send message: %v", err)
	}

	return &emptypb.Empty{}, nil
}

func (s *TelegramGRPCServer) GetUserTelegramChatId(ctx context.Context, req *telegram.GetUserTelegramChatIdRequest) (*telegram.GetUserTelegramChatIdResponse, error) {
	log.Printf("gRPC: GetUserTelegramChatId for user %s", req.UserUuid)

	userTelegramID, err := s.bot.GetUserTelegramID(ctx, req.UserUuid)
	if err != nil {
		return nil, status.Errorf(codes.NotFound, "user telegram ID not found: %v", err)
	}

	return &telegram.GetUserTelegramChatIdResponse{
		TelegramChatId: userTelegramID,
	}, nil
}